# Part of Odoo. See LICENSE file for full copyright and licensing details.

import base64
import io
import zipfile

from openpyxl import load_workbook
from openpyxl.cell.cell import TYPE_ERROR
from openpyxl.utils.exceptions import InvalidFileException

from odoo import fields, models
from odoo.exceptions import UserError
from odoo.tools import remove_accents

# The Excel file is a data contract defined by the requirements document, not a UI
# text: its headers and status values are kept as literal Spanish constants here.
# Maps the normalized (stripped, lower-cased) Excel header to the (field key on the
# row dict, display label used in error messages).
EXCEL_COLUMNS = {
    'fecha': ('date', "Fecha"),
    'cliente': ('partner_name', "Cliente"),
    'vendedor': ('user_name', "Vendedor"),
    'producto': ('product_name', "Producto"),
    'cantidad': ('quantity', "Cantidad"),
    'valor unitario': ('price_unit', "Valor Unitario"),
    'valor total': ('price_total', "Valor Total"),
    'estado': ('state', "Estado"),
}

STATE_MAPPING = {'borrador': 'draft', 'confirmada': 'confirmed', 'cancelada': 'cancelled'}

MAX_ERRORS_SHOWN = 50


class LydSaleRecordImport(models.TransientModel):
    _name = 'lyd.sale.record.import'
    _description = 'Import Sale Records from Excel'

    file = fields.Binary(string="Excel File", required=True, attachment=False)
    file_name = fields.Char(string="File Name")

    def action_import(self):
        self.ensure_one()
        workbook = self._load_workbook()
        sheet = workbook.worksheets[0]
        rows_iterator = sheet.iter_rows()
        try:
            header_row = next(rows_iterator)
        except StopIteration:
            raise UserError(self.env._("The Excel file has no rows.")) from None
        header_index = self._parse_header(header_row)

        rows_data = []
        errors = []
        for row_number, row in enumerate(rows_iterator, start=2):
            if all(cell.value in (None, '') for cell in row):
                continue
            row_data, row_errors = self._parse_row(row_number, row, header_index)
            if row_errors:
                errors.extend(row_errors)
            else:
                rows_data.append(row_data)

        if not rows_data and not errors:
            raise UserError(self.env._("The Excel file has no data rows."))
        if errors:
            raise UserError(self._format_errors(errors))

        partner_cache = {}
        user_cache = {}
        product_cache = {}
        new_partners = 0
        new_users = 0
        new_products = 0
        vals_list = []
        for row_data in rows_data:
            partner, partner_created = self._find_or_create_partner(row_data['partner_name'], partner_cache)
            user, user_created = self._find_or_create_user(row_data['user_name'], user_cache)
            product, product_created = self._find_or_create_product(row_data['product_name'], product_cache)
            new_partners += partner_created
            new_users += user_created
            new_products += product_created

            vals = {
                'date': row_data['date'],
                'partner_id': partner.id,
                'user_id': user.id,
                'product_id': product.id,
                'quantity': row_data['quantity'],
                'price_total': row_data['price_total'],
                'state': row_data['state'],
                'import_file_name': self.file_name,
            }
            if row_data['price_unit'] is not None:
                vals['price_unit'] = row_data['price_unit']
            vals_list.append(vals)

        records = self.env['lyd.sale.record'].create(vals_list)
        adjusted_count = len(records.filtered('price_unit_adjusted'))

        action = self.env['ir.actions.actions']._for_xml_id('lyd_sale_record.lyd_sale_record_action')
        return {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': self.env._("Import successful"),
                'message': self.env._(
                    "%(count)s sale records imported. New customers: %(partners)s, "
                    "salespeople: %(users)s, products: %(products)s. "
                    "Unit price adjusted in %(adjusted)s rows.",
                    count=len(records), partners=new_partners, users=new_users,
                    products=new_products, adjusted=adjusted_count,
                ),
                'type': 'success',
                'next': action,
            },
        }

    def _load_workbook(self):
        """Check the file format (D11) and open it as an Excel workbook."""
        if not (self.file_name or '').lower().endswith('.xlsx'):
            raise UserError(self.env._("Unsupported format. Please upload a file with the .xlsx extension."))
        try:
            content = base64.b64decode(self.file)
            return load_workbook(io.BytesIO(content), data_only=True, read_only=True)
        except (zipfile.BadZipFile, InvalidFileException, KeyError, ValueError) as error:
            raise UserError(self.env._("The file could not be read. It may be corrupted or not a valid .xlsx file.")) from error

    def _parse_header(self, header_row):
        """Normalize the header row and check that all the required columns (D11/EXCEL_COLUMNS) are present."""
        header_index = {}
        for col_index, cell in enumerate(header_row):
            normalized = str(cell.value).strip().lower() if cell.value is not None else ''
            if normalized in EXCEL_COLUMNS:
                header_index[EXCEL_COLUMNS[normalized][0]] = col_index
        missing = [label for field_key, label in EXCEL_COLUMNS.values() if field_key not in header_index]
        if missing:
            raise UserError(self.env._(
                "The Excel file is missing the following columns: %(columns)s.",
                columns=", ".join(missing),
            ))
        return header_index

    def _row_error(self, row_number, column, reason):
        return self.env._('Row %(row)s, column "%(column)s": %(reason)s', row=row_number, column=column, reason=reason)

    def _parse_row(self, row_number, row, header_index):
        """Validate a single data row and return ``(row_data, errors)``.

        ``row_data`` is only meaningful when ``errors`` is empty.
        """
        errors = []

        def cell_at(field_key):
            return row[header_index[field_key]]

        for field_key in header_index:
            if cell_at(field_key).data_type == TYPE_ERROR:
                errors.append(self._row_error(
                    row_number, dict(EXCEL_COLUMNS.values())[field_key],
                    self.env._("The cell contains an error value."),
                ))

        date_value = None
        try:
            date_value = fields.Date.to_date(cell_at('date').value)
        except (ValueError, TypeError):
            date_value = None
        if not date_value:
            errors.append(self._row_error(
                row_number, "Fecha",
                self.env._("Invalid date. Expected a date or text in YYYY-MM-DD format."),
            ))

        partner_name = str(cell_at('partner_name').value or '').strip()
        if not partner_name:
            errors.append(self._row_error(row_number, "Cliente", self.env._("This field is required.")))

        user_name = str(cell_at('user_name').value or '').strip()
        if not user_name:
            errors.append(self._row_error(row_number, "Vendedor", self.env._("This field is required.")))

        product_name = str(cell_at('product_name').value or '').strip()
        if not product_name:
            errors.append(self._row_error(row_number, "Producto", self.env._("This field is required.")))

        quantity = cell_at('quantity').value
        if not isinstance(quantity, (int, float)) or isinstance(quantity, bool) or quantity <= 0:
            errors.append(self._row_error(
                row_number, "Cantidad", self.env._("Expected a number greater than zero."),
            ))

        price_total = cell_at('price_total').value
        if not isinstance(price_total, (int, float)) or isinstance(price_total, bool) or price_total <= 0:
            errors.append(self._row_error(
                row_number, "Valor Total", self.env._("Expected a number greater than zero."),
            ))

        price_unit_cell_value = cell_at('price_unit').value
        price_unit = None
        if price_unit_cell_value not in (None, ''):
            if not isinstance(price_unit_cell_value, (int, float)) or isinstance(price_unit_cell_value, bool):
                errors.append(self._row_error(row_number, "Valor Unitario", self.env._("Expected a number.")))
            else:
                price_unit = price_unit_cell_value

        raw_state = cell_at('state').value
        if raw_state in (None, ''):
            errors.append(self._row_error(row_number, "Estado", self.env._("This field is required.")))
            state = False
        else:
            state = self._parse_state(raw_state)
            if not state:
                errors.append(self._row_error(
                    row_number, "Estado",
                    self.env._(
                        "Unknown status %(value)r. Expected one of: %(values)s.",
                        value=raw_state, values=", ".join(sorted(STATE_MAPPING)),
                    ),
                ))

        if errors:
            return None, errors

        return {
            'date': date_value,
            'partner_name': partner_name,
            'user_name': user_name,
            'product_name': product_name,
            'quantity': quantity,
            'price_unit': price_unit,
            'price_total': price_total,
            'state': state,
        }, []

    def _parse_state(self, raw_value):
        value = str(raw_value).strip().lower()
        selection_keys = dict(self.env['lyd.sale.record']._fields['state'].selection)
        return STATE_MAPPING.get(value) or (value if value in selection_keys else False)

    def _format_errors(self, errors):
        shown = errors[:MAX_ERRORS_SHOWN]
        if len(errors) > len(shown):
            shown = shown + [self.env._("...and %(count)s more", count=len(errors) - len(shown))]
        return self.env._(
            "The file could not be imported. %(count)s error(s) were found:\n%(details)s",
            count=len(errors), details="\n".join(shown),
        )

    def _find_or_create_partner(self, name, cache):
        if name in cache:
            return cache[name], False
        domain = [('name', '=ilike', name), *self.env['res.partner']._check_company_domain(self.env.company)]
        partner = self.env['res.partner'].search(domain, limit=1)
        created = False
        if not partner:
            partner = self.env['res.partner'].sudo().create({'name': name})
            created = True
        cache[name] = partner
        return partner, created

    def _find_or_create_product(self, name, cache):
        if name in cache:
            return cache[name], False
        domain = [('name', '=ilike', name), *self.env['product.product']._check_company_domain(self.env.company)]
        product = self.env['product.product'].search(domain, limit=1)
        created = False
        if not product:
            product = self.env['product.product'].sudo().create({'name': name})
            created = True
        cache[name] = product
        return product, created

    def _find_or_create_user(self, name, cache):
        if name in cache:
            return cache[name], False
        Users = self.env['res.users'].with_context(active_test=False)
        user = Users.search([('name', '=ilike', name), ('share', '=', False)], order='active desc, id', limit=1)
        created = False
        if not user:
            login = self._generate_user_login(name)
            user = self.env['res.users'].sudo().create({'name': name, 'login': login})
            created = True
        cache[name] = user
        return user, created

    def _generate_user_login(self, name):
        """Build a free, ASCII login for a new salesperson (N2), checking archived users too."""
        Users = self.env['res.users'].with_context(active_test=False)
        base_login = '.'.join(remove_accents(name.strip().lower()).split())
        login = base_login
        suffix = 2
        while Users.search_count([('login', '=', login)]):
            login = f"{base_login}.{suffix}"
            suffix += 1
        return login

